tool_input.script:
export const meta = {
  name: 'issue9-reconcile',
  description: 'Gather context and verify reconciliation of local issue-#9 changes against origin/main',
  phases: [{ title: 'Context' }, { title: 'Verify' }, { title: 'Critic' }],
}
const REPO = '/Users/new-jose/repos/aitools'
const R = REPO + '/.scratch/session-360aa8f3-8/recon'
const BG = `Background (already established, do not re-derive): In ${REPO}, local main is 28 commits behind origin/main. Four files have STAGED local changes: scripts/build-deploy.sh, scripts/check-hook-parity.py, scripts/check-post-push.ps1, scripts/check-post-push.sh. The full local diff is at ${R}/local-issue9.patch. These changes implement open GitHub issue #9 (nobul-tech/aitools): replace build-deploy.sh's hardcoded hook preflight list with a hooks-manifest.json-driven loop (+ explicit node requirement), delete dead HOOK_* and AITOOLS_LIB_* variables, and extend check-hook-parity.py + check-post-push step 32 (sh+ps1) to audit build-deploy.sh for hardcoded hook filenames. Only build-deploy.sh was ALSO changed on origin/main (commits 346fd32 and 51a34d8: removed CLAUDE_* prefs embedding, added setup-google-chrome copy block) -- disjoint hunks; git merge-file merged cleanly to ${R}/bd-trial.sh, and check-hook-parity.py passes on the merged tree. Read-only: do NOT modify the main working tree, index, or branches in ${REPO}. Use git show/git log/gh read commands. Report concrete facts with file:line and commit SHAs; say "not found" rather than guessing.`
const FIND = {
  type: 'object',
  properties: {
    summary: { type: 'string' },
    risks: { type: 'array', items: { type: 'object', properties: { item: { type: 'string' }, evidence: { type: 'string' }, severity: { type: 'string', enum: ['blocker', 'must-fix', 'follow-up', 'info'] } }, required: ['item', 'evidence', 'severity'] } },
  },
  required: ['summary', 'risks'],
}
const READERS = [
  { key: 'history', prompt: `${BG}\n\nTask: Read RELEASE_NOTES (find the file at repo root on origin/main via git show origin/main:<path>), the full commit messages of all 28 commits HEAD..origin/main (git log --format=full HEAD..origin/main), and the last 20 GitHub issues (gh issue list --repo nobul-tech/aitools --state all --limit 20, then gh issue view on any touching hooks, build-deploy, manifest, check-post-push, parity, node). Determine: (1) did any remote commit or release partially fix issue #9 or change hook-preflight/parity semantics; (2) what version number the next release should take (latest tag is v0.73.2 -- check versioning conventions in RELEASE_NOTES and in scripts that hold the version string); (3) any issue/PR that conflicts with or duplicates the local change. Also check the three new remote branches (origin/claude/fable-status-q9ch93, origin/claude/tender-goldberg-gae94k, origin/cursor/cloud-env-setup-28cd) and open PRs (gh pr list --repo nobul-tech/aitools --state open) for edits to the four files.` },
  { key: 'libs', prompt: `${BG}\n\nTask: On origin/main, read scripts/aitools, scripts/aitools.ps1, every scripts/aitools* file, and every file matching *lib* under scripts/ and shared/ (git ls-tree -r --name-only origin/main | grep). Determine: (1) does anything consume the variables local removes (HOOK_*, AITOOLS_LIB_BASH, AITOOLS_LIB_PS1) or source build-deploy.sh expecting them; (2) how build-deploy.sh is invoked on Windows (Git Bash) and macOS, and whether node is guaranteed on PATH at that point -- the new hard 'node is required' exit could break a path that previously worked (e.g. Windows Git Bash PATH shadowing, Claude Code web/cloud env from commit 51a34d8); (3) whether inline_lib_bash/inline_lib_ps1 read lib files directly (confirming AITOOLS_LIB_* is dead). Cite file:line.` },
  { key: 'reference', prompt: `${BG}\n\nTask: Read every file under reference/ on origin/main (git ls-tree origin/main reference/, git show). Also read shared/hooks/hooks-manifest.json meta and .claude/rules/script-standards.md + .claude/rules/cross-platform.md. Find every doc passage that (a) describes build-deploy.sh's hook preflight as a hardcoded list, (b) documents check-post-push step 32 / check-hook-parity.py arguments or scope, (c) lists build-deploy.sh prerequisites (node), (d) documents the exemptions table or error-handling rules the new code must satisfy (e.g. '|| {' block, here-string loop, 'command -v node >/dev/null 2>&1'). Report which docs become stale after the local change lands and must be updated in the same PR, noting which are protected source-of-truth files (per .claude/rules/sources-of-truth.md) requiring user approval.` },
  { key: 'standards', prompt: `${BG}\n\nTask: Audit the local diff (${R}/local-issue9.patch) and the merged build-deploy (${R}/bd-trial.sh) against .claude/rules/script-standards.md, cross-platform.md, and the build-deploy logging override exception (blog/blog_ok/blog_error). Check: structured logging, error suppression with result checks, grep -P avoidance, bash 3.2 compatibility on macOS (here-strings, process substitution), python type hints in check-hook-parity.py, PS1/sh parity of step 32 edits. Also a substring-match false-positive concern: check-hook-parity.py flags any manifest filename appearing anywhere in build-deploy.sh (comments included) -- list every manifest/deploy filename and grep bd-trial.sh for each to confirm zero hits and judge whether the substring check is too brittle (e.g. a future comment mentioning 'ait-harvest.py' fails the build check). Report pass/fail per item.` },
]
phase('Context')
const ctx = await pipeline(READERS, r => agent(r.prompt, { label: 'read:' + r.key, phase: 'Context', schema: FIND }).then(x => x && ({ key: r.key, ...x })))

phase('Verify')
const verify = await agent(`${BG}\n\nTask: End-to-end verify the reconciled result in an ISOLATED git worktree (you are running in one). Steps: (1) git checkout --detach origin/main; (2) git apply ${R}/local-issue9.patch -- if it fails, use git apply -3 and report exactly what conflicted; (3) bash -n scripts/build-deploy.sh; (4) run bash scripts/build-deploy.sh > ${R}/verify-build.log 2>&1 and report exit code, the 'Preflight OK: N hook/helper file(s)' line, and GENERATED count; compare deploy/ output against a baseline build of plain origin/main (stash/checkout to build baseline into a separate log ${R}/verify-baseline.log, then diff -r the two deploy/ trees saved under ${R}/deploy-merged and ${R}/deploy-baseline) -- expected: identical deploy output except nothing (dead-code removal should be output-neutral); (5) python3 scripts/check-hook-parity.py with all 4 args; (6) negative test: temporarily rename one manifest-listed hook file and confirm build-deploy exits 1 with the manifest error, then restore; (7) negative test: append a comment containing a manifest hook filename to build-deploy.sh and confirm parity check exits 1, then restore; (8) run bash scripts/check-post-push.sh --extensive (or its equivalent flag -- read the script) redirecting to ${R}/verify-postpush.log and report step 32 result and overall summary (other step failures unrelated to this change: list but mark unrelated). Do not push or commit anything.`, { label: 'verify:e2e', phase: 'Verify', isolation: 'worktree', schema: FIND })

phase('Critic')
const all = [...ctx.filter(Boolean), verify && { key: 'verify', ...verify }].filter(Boolean)
const critic = await agent(`${BG}\n\nYou are a skeptical completeness critic. Below are findings from 5 agents. Try to REFUTE the conclusion "the local change can be landed by rebasing onto origin/main with a clean merge, no semantic conflict". Re-check the single strongest risk each agent raised against the actual repo (git show origin/main:...). Also consider the OTHER staged content in the index (harvesting/* files, .mcp.json, .cursor/mcp.json, harvesting/harvest-manifest.json shown as MM) -- run git -C ${REPO} status --porcelain and git -C ${REPO} diff HEAD origin/main --stat -- harvesting/ .mcp.json .cursor/ and say whether those collide with remote. Output: refuted (bool), the risks you confirmed as real with evidence, and anything no agent checked.\n\nFINDINGS:\n${JSON.stringify(all, null, 1)}`, { label: 'critic', phase: 'Critic', schema: { type: 'object', properties: { refuted: { type: 'boolean' }, confirmed: { type: 'array', items: { type: 'string' } }, unchecked: { type: 'array', items: { type: 'string' } }, otherStaged: { type: 'string' } }, required: ['refuted', 'confirmed', 'unchecked', 'otherStaged'] } })
return { findings: all, critic }
